import{_ as e,c as r,o as p,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"56、【旅】 艮下离上","description":"周易尚氏学 - 56、【旅】 艮下离上","frontmatter":{"title":"56、【旅】 艮下离上","description":"周易尚氏学 - 56、【旅】 艮下离上"},"headers":[],"relativePath":"zh/classics/shangshi/061.md","filePath":"zh/classics/shangshi/061.md"}'),s={name:"zh/classics/shangshi/061.md"};function h(t,a,l,n,c,d){return p(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_56、【旅】-艮下离上" tabindex="-1">56、【旅】 艮下离上 <a class="header-anchor" href="#_56、【旅】-艮下离上" aria-label="Permalink to “56、【旅】 艮下离上”">​</a></h1><p>旅之卦义。先儒皆以行旅为说。然卦名皆由卦象生。火山何以为旅。侯果孔疏皆以火在山上。势难久留。故为旅。如所诂火在山上。不久即灭耳。安见其为行旅。按易林剥之旅云。居正不安。大盗为咎。大畜之旅云。安其室庐。传母何优。是皆以居家为说。于行旅之义正相反。履之旅云。鸟子鹊雏。常与母俱。愿慕群旅。不离其巢。又晋之旅云。逐旅失群。是以旅为伴旅。卦二阴。随二阳。一阴随一阳。阳前阴后。有若伴侣。疑焦氏所诂者。于卦象为切。又释诂旅众也。卦离火。艮亦为火。火多故众。伴旅亦众也。九三象云。以旅与下。以众与下也。若作行旅。此句难通矣。又初交旅琐琐。斯其所。斯离也。行旅往来。有不离其所者哉。于行旅之义尤不合。故疑焦义是也。六五得尊位。故小亨。贞吉。</p><p>彖曰。旅。小亨。柔得中乎外而顺乎刚。上而丽乎明。是以小亨。旅贞吉也。旅之时又大矣哉。</p><p>六五上下皆阳。故曰顺乎刚。离六五云。离王公。即顺乎刚也。旅五月卦。当中夏。故曰时。</p><p>象曰。山上有火。旅。君子以明慎用刑。而不留狱。</p><p>大象以相反见义。此亦其一也。离为明。君子不敢待其明。故用刑必慎。艮为慎。兑为刑也。艮为止。君子不敢怠于事。故不留狱。艮为拘系为狱也。</p><p>初六。旅琐琐。斯其所取灾。</p><p>琐琐。陆绩郑玄皆训为小。马云疲弊视貌。按尔雅释诂。琐琐小也。注舍人曰琐琐。计谋褊浅之貌。诗节南山。琐琐姻姬。盖往来猥琐。劳弊不安也。斯释言离也。斯其所言离其所欲应四也。二得敌。故取灾。离为灾。盖初六不当位。而得敌。在下。宜静不宜动。故易林复之旅云。二人辇车。徒去其家。井沸釜鸣。不可以居。徒去其家。即离其所。并沸釜鸣。即取灾也。义详焦氏易诂。</p><h3 id="象曰。旅琐琐。志穷变也。" tabindex="-1">象曰。旅琐琐。志穷变也。 <a class="header-anchor" href="#象曰。旅琐琐。志穷变也。" aria-label="Permalink to “象曰。旅琐琐。志穷变也。”">​</a></h3><p>初不当位。二得敌。不能应四。故曰志穷。</p><p>六二。旅即次。怀其资。得僮仆贞。</p><p>举正作员吉。宜从。艮为舍。次舍也。即次。言就舍也。资财也。巽为利居中。故怀其资。艮为僮仆。二得位承阳。故得僮仆。贞下宜依举正增吉字。贞吉与下贞厉为对文。</p><h3 id="象曰。得童仆贞-终无尤也。" tabindex="-1">象曰。得童仆贞，终无尤也。 <a class="header-anchor" href="#象曰。得童仆贞-终无尤也。" aria-label="Permalink to “象曰。得童仆贞，终无尤也。”">​</a></h3><p>即次身安。怀资用足。得僮仆役使有人。故终天尤。艮初象云。志疑也。即以巽为志。杂卦云。巽伏也。心志伏在内。故巽象之。旧解命四变成坎取心象。非。</p><p>九三：旅焚其次，丧其童仆，贞厉。</p><h3 id="象曰-旅焚其次-亦以伤矣。以旅与下-其义丧也。" tabindex="-1">象曰：旅焚其次，亦以伤矣。以旅与下，其义丧也。 <a class="header-anchor" href="#象曰-旅焚其次-亦以伤矣。以旅与下-其义丧也。" aria-label="Permalink to “象曰：旅焚其次，亦以伤矣。以旅与下，其义丧也。”">​</a></h3><p>九四：旅于处，得其资斧，我心不快。</p><h3 id="象曰-旅于处-未得位也。得其资斧-心未快也。" tabindex="-1">象曰：旅于处，未得位也。得其资斧，心未快也。 <a class="header-anchor" href="#象曰-旅于处-未得位也。得其资斧-心未快也。" aria-label="Permalink to “象曰：旅于处，未得位也。得其资斧，心未快也。”">​</a></h3><p>凡九四比六五。例终升五。归妹九四曰。有待而行。待升五也。丰九四曰遇其夷主吉行也。六五曰来章。亦言回来五也。兹曰未得位。因未得五位。故处以俟也。下六五曰终以誉命。即谓四终升五也。</p><p>六五。射雉。一矢亡。终以誉命。</p><p>离为雉。兑毁折。故射雉。射必以矢。坎为矢。乃坎伏不见。故一矢亡。坎数一也。誉令闻也。艮为誉。命。爵命也。巽为命。终以誉命者。言巽命在二。虽不应五。然四必得位升五。四升五。二应之。是誉命终及于五也。</p><h3 id="象曰。终以誉命。上逮也。" tabindex="-1">象曰。终以誉命。上逮也。 <a class="header-anchor" href="#象曰。终以誉命。上逮也。" aria-label="Permalink to “象曰。终以誉命。上逮也。”">​</a></h3><p>逮及也。上逮谓二终上应五也。</p><p>上九：鸟焚其巢，旅人先笑后号咷，丧牛于易，凶。</p><p>离为鸟。中虚故为巢。巽风扇火于下故焚巢。上履阴。兑悦故先笑。三巽体。男为兆（左口）。三不应上。故后号兆。左传昭五年。纯离为牛。兑毁折。故丧牛。艮为田为易。易田畔电。牛在艮外。故丧牛于田畔。焚巢丧牛故凶。晁说之云。易古文场字。诗小雅疆场有瓜是也。</p><h3 id="象曰-以旅在上-其义焚也。丧牛于易-终莫之闻也。" tabindex="-1">象曰：以旅在上，其义焚也。丧牛于易，终莫之闻也。 <a class="header-anchor" href="#象曰-以旅在上-其义焚也。丧牛于易-终莫之闻也。" aria-label="Permalink to “象曰：以旅在上，其义焚也。丧牛于易，终莫之闻也。”">​</a></h3><p>旅众也。在上者众。不自敛抑。则高亢为祸。左传隐四年。兵犹火也。不戢将自焚。是其义也。坎为耳。坎伏故莫之闻。虞翻用爻变取震象。谓震为筐故为巢。后儒多从之。按易林离之需云。高木腐巢需坎为木。在上故曰高木。互离为巢。在泽水中。故曰腐巢。讼之解云。南徒无庐。鸟破其巢。解上震。震为南为徒。下坎为室。震在坎外。故曰南徒无庐。互离为鸟为巢。而坎为破。故曰乌破其巢。以离为巢。庶得真解。</p>',27)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
